import{_ as t,o as i,c as s,a3 as n}from"./chunks/framework.DAnVGsli.js";const c=JSON.parse('{"title":"Vorbereitung","description":"","frontmatter":{},"headers":[],"relativePath":"vorbereitung.md","filePath":"vorbereitung.md"}'),a={name:"vorbereitung.md"};function o(d,e,r,l,h,p){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="vorbereitung" tabindex="-1">Vorbereitung <a class="header-anchor" href="#vorbereitung" aria-label="Permalink to &quot;Vorbereitung&quot;">​</a></h1><p>Einmal einrichten, danach nur noch nachschlagen: Telegram-Konto, ein Bot mit Token und die Werkzeuge. Am Ende steht ein Test, der alles zusammen prüft.</p><p>Alle Befehle sind für <strong>Bash</strong> (Linux, macOS; unter Windows WSL oder Git Bash).</p><h2 id="_1-telegram-konto" tabindex="-1">1. Telegram-Konto <a class="header-anchor" href="#_1-telegram-konto" aria-label="Permalink to &quot;1. Telegram-Konto&quot;">​</a></h2><p>Du brauchst ein Telegram-Konto mit der App auf dem Handy oder dem Desktop. Bots schreibst du wie normale Kontakte an, deshalb ist die App auch zum Ausprobieren nötig.</p><h2 id="_2-einen-bot-bei-botfather-anlegen" tabindex="-1">2. Einen Bot bei BotFather anlegen <a class="header-anchor" href="#_2-einen-bot-bei-botfather-anlegen" aria-label="Permalink to &quot;2. Einen Bot bei BotFather anlegen&quot;">​</a></h2><p>BotFather ist der Bot, bei dem man alle anderen Bots anlegt und verwaltet.</p><ol><li>Suche in Telegram nach <code>@BotFather</code> (blaues Häkchen) und öffne den Chat.</li><li>Sende <code>/newbot</code>.</li><li>Wähle einen <strong>Namen</strong> (frei, z. B. <code>Mein Lern-Bot</code>).</li><li>Wähle einen <strong>Benutzernamen</strong>. Er muss auf <code>bot</code> enden und noch frei sein, z. B. <code>mein_lern_1234_bot</code>.</li><li>BotFather antwortet mit dem <strong>Token</strong>, der aussieht wie <code>123456:ABC-DEF...</code>.</li></ol><p>Dieser Bot ist dein <strong>Lern-Bot</strong> für den Lernpfad und die kleinen Anwendungen. Für Mini App und Login Widget legst du später in deren Kapiteln einen zweiten Bot an.</p><h2 id="_3-token-ablegen" tabindex="-1">3. Token ablegen <a class="header-anchor" href="#_3-token-ablegen" aria-label="Permalink to &quot;3. Token ablegen&quot;">​</a></h2><p>Der Token gehört nicht in den Code, sondern in eine Umgebungsvariable. Alle Beispiele lesen <code>TELEGRAM_BOT_TOKEN</code>.</p><p>Pro Terminal-Sitzung:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TELEGRAM_BOT_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;123456:ABC-DEF...&#39;</span></span></code></pre></div><p>Oder mit einer <code>.env</code>-Datei, die du bei Bedarf einliest. Im Repo liegt die Vorlage <code>.env.example</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # dann den Token in .env eintragen</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p><code>.env</code> steht in der <code>.gitignore</code> und wird nie committet.</p><p>Wer den Token dauerhaft haben möchte, kann den <code>export</code> in sein Shell-Profil (<code>~/.bashrc</code>) schreiben. Das ist bequem, aber der Token liegt dann im Klartext in einer weiteren Datei.</p><details class="details custom-block"><summary>Windows ohne WSL</summary><p>In PowerShell gilt für die aktuelle Sitzung: <code>$env:TELEGRAM_BOT_TOKEN=&#39;123456:ABC-DEF...&#39;</code>. Alle anderen Befehle dieser Seite sind für Bash gedacht; WSL ist der einfachste Weg.</p></details><div class="warning custom-block"><p class="custom-block-title">Der Token ist ein Passwort</p><p>Wer den Token kennt, steuert deinen Bot.</p><ul><li>Er steht bei jedem Aufruf <strong>im URL-Pfad</strong> (<code>https://api.telegram.org/bot&lt;TOKEN&gt;/getMe</code>). Deshalb loggen die Beispiele die URL nie, und das solltest du in eigenem Code auch nicht tun.</li><li>Schreibe ihn nie in Code, Commits, Screenshots oder Chat-Nachrichten.</li><li>Ist er trotzdem geleakt, sende BotFather <code>/revoke</code>. Der alte Token ist sofort ungültig und du bekommst einen neuen.</li></ul></div><h3 id="ubung-einen-token-widerrufen" tabindex="-1">Übung: einen Token widerrufen <a class="header-anchor" href="#ubung-einen-token-widerrufen" aria-label="Permalink to &quot;Übung: einen Token widerrufen&quot;">​</a></h3><p>Übe den Ernstfall mit einem Wegwerf-Bot, damit du ihn im Notfall kennst.</p><ol><li>Lege bei BotFather mit <code>/newbot</code> einen zweiten Bot an, z. B. <code>wegwerf_1234_bot</code>.</li><li>Prüfe den Token: <code>curl &quot;https://api.telegram.org/bot&lt;TOKEN&gt;/getMe&quot;</code> liefert <code>&quot;ok&quot;:true</code>.</li><li>Sende BotFather <code>/revoke</code> und wähle den Wegwerf-Bot. Du bekommst einen neuen Token.</li><li>Wiederhole Schritt 2 mit dem <strong>alten</strong> Token. Jetzt kommt <code>&quot;ok&quot;:false</code> mit <code>401 Unauthorized</code>.</li><li>Lösche den Bot mit <code>/deletebot</code>.</li></ol><h2 id="_4-werkzeuge" tabindex="-1">4. Werkzeuge <a class="header-anchor" href="#_4-werkzeuge" aria-label="Permalink to &quot;4. Werkzeuge&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Werkzeug</th><th>Zweck</th><th>Prüfen</th></tr></thead><tbody><tr><td>JDK 21</td><td>Beispiele kompilieren und starten</td><td><code>java -version</code> zeigt 21</td></tr><tr><td><code>curl</code></td><td>API-Aufrufe von Hand</td><td><code>curl --version</code></td></tr><tr><td>Git</td><td>Repo klonen</td><td><code>git --version</code></td></tr><tr><td><code>./mvnw</code></td><td>Maven-Wrapper im Repo, lädt Maven selbst</td><td><code>./mvnw -v</code> im Repo</td></tr></tbody></table><p>Ab <a href="/learn_telegram/lektionen/06-webhooks.html">Lektion 6</a> (optional) und <a href="/learn_telegram/lektionen/11-mini-apps.html">Lektion 11</a> (Pflicht) brauchst du zusätzlich <code>cloudflared</code>. Du installierst es erst dann, die Seite <a href="/learn_telegram/werkzeuge.html">Werkzeuge</a> erklärt es.</p><p>Nutze im Repo immer <code>./mvnw</code> statt eines selbst installierten <code>mvn</code>. Der Wrapper bringt die Maven-Version mit, für die das Projekt getestet ist.</p><p>Hole dir anschließend den Code der Beispiele:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/ckroeger/learn_telegram.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> learn_telegram</span></span></code></pre></div><h2 id="_5-abschlusstest" tabindex="-1">5. Abschlusstest <a class="header-anchor" href="#_5-abschlusstest" aria-label="Permalink to &quot;5. Abschlusstest&quot;">​</a></h2><p>Dieser Test prüft Werkzeuge, Token und Netz in einem Zug.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mvnw</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.telegram.org/bot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TELEGRAM_BOT_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/getMe&quot;</span></span></code></pre></div><p>Die erste Zeile zeigt Maven und dein JDK 21. Die zweite antwortet mit dem Profil deines Bots:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;is_bot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;first_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Mein Lern-Bot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mein_lern_1234_bot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>Siehst du <code>&quot;ok&quot;:true</code>, bist du bereit für den <a href="/learn_telegram/lektionen/quick-start.html">Quick-Start</a>.</p><table tabindex="0"><thead><tr><th>Meldung</th><th>Ursache</th></tr></thead><tbody><tr><td><code>&quot;ok&quot;:false</code> mit <code>401 Unauthorized</code></td><td>Token falsch, unvollständig oder widerrufen</td></tr><tr><td><code>&quot;ok&quot;:false</code> mit <code>404 Not Found</code></td><td>Im Pfad fehlt das Wort <code>bot</code> vor dem Token</td></tr><tr><td><code>curl: (6) Could not resolve host</code></td><td>Kein Netz oder Proxy</td></tr><tr><td>Leerer Token in der URL (<code>/bot/getMe</code>)</td><td><code>TELEGRAM_BOT_TOKEN</code> ist nicht gesetzt, <code>echo \${TELEGRAM_BOT_TOKEN:+gesetzt}</code> prüft das</td></tr></tbody></table>`,35)])])}const u=t(a,[["render",o]]);export{c as __pageData,u as default};
